// This only works though if we know that the match is sandwiched
// between two \W codepoints. This only occurs when neither ^ nor $
// match. The ^ and $ line anchors can match not only at the beginning
// and end of the haystack, but also at line boundaries anywhere in
// the haystack. So we bail whenever the match boundaries are adjacent
// to a line terminator, since in that case the anchor alternative may
// have been used instead of the \W alternative. (When a line
// terminator is present at either boundary, it is ambiguous whether
// the \W alternative or the line anchor alternative matched, and we
// cannot know whether the boundary codepoint belongs to the original
// match or not.)
//
// The reason why we cannot handle the ^/$ cases here is because we
// can't assume anything about the original pattern. (Try commenting
// out the checks for ^/$ below and run the tests to see examples.)
//
// Note that we check for both \n and \r. For the start boundary, a
// line anchor can only match immediately after a \n (or at the start
// of the haystack). For the end boundary, a line anchor can match
// immediately before a \n, or immediately before a \r\n (in which
// case \r is at the boundary). Since \r and \n are also \W, we cannot
// disambiguate which alternative matched and thus must defer to the
// slower but correct implementation.
let input = Input::new(haystack).span(at..haystack.len());
let mut cand = match self.regex.find(input) {
    None => return Ok(None),
    Some(m) => Match::new(m.start(), m.end()),
};
if cand.start() == 0
    || cand.end() == haystack.len()
    || haystack[cand.start() - 1] == b'\n'
    || haystack[cand.end()] == b'\n'
    || haystack[cand.end()] == b'\r'
{
    return Err(());
}

